  1 | import { useCallback, useRef, useState } from "react";
  2 | import { usePlayerWithAudio } from "./hooks/usePlayerWithAudio";
  3 | import { useMetadata } from "./hooks/useMetadata";
  4 | import {
  5 |   TitleBar,
  6 |   Playlist,
  7 |   PlayerControls,
  8 |   ProgressBar,
  9 |   StatusBar,
 10 | } from "./components";
 11 | import type { Track } from "./types";
 12 | 
 13 | const SAMPLE_TRACKS: Track[] = [
 14 |   {
 15 |     id: "1",
 16 |     title: "Música Exemplo 1",
 17 |     artist: "Artista Exemplo",
 18 |     duration: 234,
 19 |   },
 20 |   {
 21 |     id: "2",
 22 |     title: "Música Exemplo 2",
 23 |     artist: "Artista Exemplo",
 24 |     duration: 198,
 25 |   },
 26 |   {
 27 |     id: "3",
 28 |     title: "Música Exemplo 3",
 29 |     duration: 312,
 30 |   },
 31 | ];
 32 | 
 33 | function App() {
 34 |   const {
 35 |     state,
 36 |     play,
 37 |     pause,
 38 |     next,
 39 |     prev,
 40 |     seek,
 41 |     setVolume,
 42 |     addTrack,
 43 |     toggleShuffle,
 44 |     reorderPlaylist,
 45 |   } = usePlayerWithAudio(SAMPLE_TRACKS);
 46 | 
 47 |   const { processFiles } = useMetadata();
 48 |   const [isLoading, setIsLoading] = useState(false);
 49 | 
 50 |   const fileInputRef = useRef<HTMLInputElement>(null);
 51 | 
 52 |   const handleSelectTrack = (track: Track) => {
 53 |     play(track);
 54 |   };
 55 | 
 56 |   const handleOpenFile = () => {
 57 |     fileInputRef.current?.click();
 58 |   };
 59 | 
 60 |   const handleFileChange = useCallback(
 61 |     async (e: React.ChangeEvent<HTMLInputElement>) => {
 62 |       const files = e.target.files;
 63 |       if (!files || files.length === 0) return;
 64 | 
 65 |       setIsLoading(true);
 66 | 
 67 |       try {
 68 |         const fileArray = Array.from(files);
 69 |         const tracks = await processFiles(fileArray);
 70 | 
 71 |         for (const track of tracks) {
 72 |           addTrack(track);
 73 |         }
 74 | 
 75 |         // If nothing is playing, start with the first track
 76 |         if (!state.currentTrack && tracks.length > 0) {
 77 |           play(tracks[0]);
 78 |         }
 79 |       } catch (err) {
 80 |         console.error("[Llama Player] Erro ao processar arquivos:", err);
 81 |       } finally {
 82 |         setIsLoading(false);
 83 |       }
 84 | 
 85 |       // Reset input so the same file can be selected again
 86 |       e.target.value = "";
 87 |     },
 88 |     [processFiles, addTrack, state.currentTrack, play]
 89 |   );
 90 | 
 91 |   return (
 92 |     <div className="app">
 93 |       <TitleBar />
 94 | 
 95 |       <main className="main-content">
 96 |         <div className="toolbar">
 97 |           <button
 98 |             className="toolbar-btn"
 99 |             onClick={handleOpenFile}
100 |             disabled={isLoading}
101 |             title="Abrir arquivo de áudio"
102 |           >
103 |             {isLoading ? "⏳ Lendo metadados..." : "📂 Abrir arquivo"}
104 |           </button>
105 |           <input
106 |             ref={fileInputRef}
107 |             type="file"
108 |             accept="audio/*"
109 |             multiple
110 |             style={{ display: "none" }}
111 |             onChange={handleFileChange}
112 |           />
113 |         </div>
114 | 
115 |         <Playlist
116 |           tracks={state.playlist}
117 |           currentTrackId={state.currentTrack?.id ?? null}
118 |           isPlaying={state.isPlaying}
119 |           onSelectTrack={handleSelectTrack}
120 |           onReorderPlaylist={reorderPlaylist}
121 |         />
122 | 
123 |         <PlayerControls
124 |           currentTrack={state.currentTrack}
125 |           isPlaying={state.isPlaying}
126 |           isShuffled={state.isShuffled}
127 |           onPlay={() => play()}
128 |           onPause={pause}
129 |           onNext={next}
130 |           onPrev={prev}
131 |           onToggleShuffle={toggleShuffle}
132 |         />
133 | 
134 |         <ProgressBar
135 |           currentTime={state.currentTime}
136 |           duration={state.duration}
137 |           onSeek={seek}
138 |         />
139 |       </main>
140 | 
141 |       <StatusBar
142 |         isPlaying={state.isPlaying}
143 |         volume={state.volume}
144 |         onVolumeChange={setVolume}
145 |       />
146 |     </div>
147 |   );
148 | }
149 | 
150 | export default App;
151 |
